CREATE TABLE external_channel_cache(cache_key text PRIMARY KEY,payload jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE external_publish_quotes(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),actor_id text NOT NULL REFERENCES users(id),article_id text NOT NULL REFERENCES articles(id),snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE external_publish_batches(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),actor_id text NOT NULL REFERENCES users(id),quote_id text NOT NULL REFERENCES external_publish_quotes(id),request_key text NOT NULL,billing_id text UNIQUE NOT NULL REFERENCES billing_orders(id),status text NOT NULL DEFAULT 'queued',mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,request_key));
CREATE TABLE external_publish_orders(id text PRIMARY KEY,batch_id text NOT NULL REFERENCES external_publish_batches(id),channel jsonb NOT NULL,amount_cents integer NOT NULL CHECK(amount_cents>=0),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','submitting','processing','published','failed','review')),provider_order_id text,result_url text,error text,lease_until timestamptz,next_poll_at timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX external_publish_dispatch ON external_publish_orders(status,next_poll_at);
